/* 绑定花名册列表 */
function renderRoster(){
  var roster=mvuObj('绑定花名册');
  var keys=Object.keys(roster).filter(function(k){return k&&roster[k]&&roster[k].姓名});
  var body='';
  if(keys.length===0){
    body='<div style="text-align:center;color:var(--c-dim);padding:10px;font-size:var(--fs-sm)">暂无绑定数据</div>';
  }else{
    for(var i=0;i<keys.length;i++){
      var key=keys[i];
      var w=roster[key];
      var name=w.姓名||'无';
      var stage=w.绑定等级||'A10';
      var status=w.状态||'待绑定';
      var stageCls=status==='已绑定'?'pink':(status==='绑定中'?'warn':(status==='待绑定'?'':'safe'));
      body+='<div class="wcard" data-act="woman-detail" data-key="'+esc(key)+'">'
        +'<div class="wcard-row">'
        +'<span class="wcard-name">'+esc(name)+'</span>'
        +'<span class="wcard-stage '+stageCls+'">'+esc(stage)+'</span>'
        +'</div>'
        +'<div class="wcard-stats">'
        +'<span>深度:'+esc(w.绑定深度||0)+'</span>'
        +'<span>清醒:'+esc(w.清醒频率||0)+'</span>'
