/* 主渲染 */
function render(){
  var loadingEl=document.getElementById('sb-loading');
  var bodyEl=document.getElementById('sb-body');
  if(!bodyEl)return;
  if(State.loading){loadingEl.style.display='';bodyEl.style.display='none';return}
  try{
    loadingEl.style.display='none';bodyEl.style.display='';
    bodyEl.innerHTML=renderHeader()+renderVillain()+renderUser()+renderNegotiation()+renderRoster()+renderAttrs()+renderSkills()+renderComments()+renderMemory();
  }catch(e){
    /* 渲染失败时也要隐藏 loading，显示错误信息 */
    try{loadingEl.style.display='none';bodyEl.style.display='';bodyEl.innerHTML='<div style="padding:12px;color:#f87171;font-size:12px">状态栏渲染错误: '+esc(e.message||String(e))+'</div>'}catch(x){}
  }
}

