  var overlay=document.getElementById('modal-overlay');
  var modal=document.getElementById('modal-content');
  modal.innerHTML='<div class="modal-title"><span>'+esc(title)+'</span><button class="modal-close" data-act="close-modal">✕</button></div>'+content;
  overlay.className='modal-overlay show';
}
function closeModal(){document.getElementById('modal-overlay').className='modal-overlay'}

/* 花名册详情 */
function showWomanDetail(key){
  var roster=mvuObj('绑定花名册');
  var w=roster[key];
  if(!w){showModal('错误','<p>未找到：'+esc(key)+'</p>');return}
  var content=renderWomanBody(w,w.姓名);
  showModal(esc(w.姓名||key)+' · 完整详情',content);
}

/* refresh - 异步版本，参考同级生2/暗黑地牢生产级实现 */
async function refresh(){
  if(State._refreshing)return;
  State._refreshing=true;State.refreshing=true;
  /* 第一步：用 embed 快照快速渲染一次（避免界面空白） */
  try{
    var stat=readStatDataSync();
    if(hasData(stat)){State.mvu=stat;State.loading=false}
    render();
  }catch(e){State.loading=false;State._refreshing=false;State.refreshing=false;render();return}
  /* 第二步：异步获取最新 MVU 数据 */
  try{
    var realStat=await readStatDataAsync();
    if(hasData(realStat)){State.mvu=realStat;State.loading=false}
    State._refreshing=false;State.refreshing=false;
    render();requestStatFromBridge();
  }catch(e){State._refreshing=false;State.refreshing=false;render()}
}

/* 事件绑定 */
function bindEvents(){
  var root=document.getElementById('sb-root');
  root.addEventListener('toggle',function(e){
    var t=e.target;
    if(t&&t.tagName==='DETAILS'){var key=t.getAttribute('data-key');if(key){State.expanded[key]=t.hasAttribute('open')}}
  },true);
  root.addEventListener('click',function(e){
    var t=e.target.closest('[data-act]');
    if(!t)return;
    var act=t.getAttribute('data-act');
    if(act==='refresh'){refresh()}
    else if(act==='woman-detail'){showWomanDetail(t.getAttribute('data-key'))}
  });
  document.getElementById('modal-overlay').addEventListener('click',function(e){
    var t=e.target.closest('[data-act]');
    if(t&&t.getAttribute('data-act')==='close-modal'){closeModal()}
  });
}

/* 初始化 */
(function init(){
  try{bindEvents()}catch(e){}
  var autoRefresh=function(){try{setTimeout(refresh,800)}catch(e){}};
  try{if(typeof eventOn==='function'){eventOn('GENERATION_ENDED',autoRefresh);eventOn('MESSAGE_EDITED',autoRefresh);eventOn('mag_variable_update_ended',autoRefresh)}}catch(e){}
  try{var Mvu=getMvu();if(Mvu&&Mvu.events&&Mvu.events.VARIABLE_UPDATE_ENDED&&typeof eventOn==='function'){eventOn(Mvu.events.VARIABLE_UPDATE_ENDED,autoRefresh)}}catch(e){}
  window.addEventListener('message',function(e){
    try{
      var data=e.data;
      if(data&&data.type==='xtmd-mvu-stat-data'&&data.stat_data){
        var mesId=resolveMessageId();
        if(mesId>=0&&typeof data.messageId==='number'&&data.messageId>=0&&data.messageId!==mesId)return;
        if(hasMeaningfulStatData(data.stat_data)){
          cachedStatFromBridge=data.stat_data;
          cachedBridgeMessageId=typeof data.messageId==='number'?data.messageId:mesId;
          State.mvu=deepMergeStat(DEFAULT_STAT,data.stat_data);
          State.loading=false;render();
        }
        return;
      }
      var t=(data&&data.type)||data||'';
      if(typeof t==='string'&&(t.indexOf('generation_ended')>=0||t.indexOf('message_edit')>=0))autoRefresh();
    }catch(x){}
  });
  try{var embedded=parseEmbeddedStat();if(embedded){cachedStatFromBridge=embedded;cachedBridgeMessageId=resolveMessageId()}}catch(e){}
  try{requestStatFromBridge()}catch(e){}
  try{refresh()}catch(e){State.loading=false;render()}
  /* 超时兜底：3秒后如果仍在loading，强制用DEFAULT_STAT渲染 */
  setTimeout(function(){if(State.loading){State.loading=false;State.mvu=DEFAULT_STAT;render()}},3000);
})();
</script>
</body>
</html>

