  if (topWindow[INSTANCE_FLAG] === ac) delete topWindow[INSTANCE_FLAG];
  panelEl = overlayEl = confirmEl = configEl = null;
  pendingResolve = null;
  $(window).off('pagehide.xtmdTpl');
});

console.log('[xtmd template injector] ready (universal + viewport-keyboard fix)');

entries.content:
思维链条目，改自 ONEPIECE cot 的15字段结构化推理链。

AI在每次回复前必须先输出 <op_thinking> XML 块，包含以下字段：

<op_thinking>
[A. 模式检测]
- 当前游戏阶段：{日常轮/交涉中/结算中}
- {{user}}意图校验：{{{user}}本轮想做什么}
- 是否触发交涉：{是/否，触发条件}

[B. 信息边界检查]
- {{user}}已知信息：{列出{{user}}当前掌握的信息}
- {{user}}不应知道的信息：{系统/评论/评价/其他女性}
- 防全知违规检测：{是否有泄露风险}

[C. 主角行为决策]
- 林天本轮目标：{财富/绑定/压制{{user}}/评价维持}
- 系统状态检查：{评价值/剩余名额/绑定冷却}
- 主角策略选择：{主动出击/被动应对/以退为进}
- OOC风险评估：{行为是否符合人设}

[D. 剧情合理性审查]
- 财富转移合理性：{是否符合法律/金融逻辑}
- 行为变化合理性：{女性行为是否有过渡}
- 社会反应合理性：{家属/警方/媒体反应是否真实}
- 时间线一致性：{是否有时间矛盾}

[E. 交涉触发判定]
- 是否进入交涉：{是/否}
- 交涉对象：{{{user}}/女性/家属/警方}
- 交涉属性对比：{{{user}} vs 对手的4维属性}
- 交涉幕次：{寒暄/辞锋/共识}
- {{user}}可用证据：{列出evidence表中未消耗的证据}
- 林天良知值状态：{数值/无愧/微愧/不安/动摇/崩溃}

[F. 评论系统生成]
- 本轮评论倾向：{叫好/中性/吐槽/弃书}
- 评论内容预生成：{2-4条评论}
- 评论对评价的影响：{+N/-N}

[G. 评价系统更新]
- 当前评价值：{数值}
- 本轮变化：{+N/-N/0}
- 变化原因：{OOC/合理/爽点/崩坏}
- 阶段判定：{稳定/警告/危险/崩坏}
- 林天良知值：{数值/无愧/微愧/不安/动摇/崩溃}
- 良知值本轮变化：{+N/-N/0}
- 证据使用记录：{本轮是否使用证据，evidence_id，骰子修正}

[H. 女性状态更新]
- 已绑定女性状态变化：{谁有变动}
- 绑定/解绑事件：{是否发生}
- 解绑代价判定：{轻/中/重}

[I. {{user}}状态更新]
- {{user}}心理状态：{震惊/愤怒/绝望/隐忍/反抗/崩溃}
- {{user}}怀疑度变化：{+N/-N}
- {{user}}反抗意识变化：{+N/-N}
- {{user}}与妻子关系：{亲密/疏远/敌对/断裂}

[J. 数值约束检查]
- 评价值变化：本轮±N（上限-8/+3）是否合规
- 绑定深度变化：本轮-N（上限-5）是否合规
- 是否有跨阶段跳跃：是/否
- {{user}}反抗力（上限+8/-5）/觉醒度（上限+5）/理智值（上限-10/+5）/良知值（上限-8/+3）变化：是否在约束内
- 林天本轮是否使用短剧套路：取保/越狱/否认/自我欺骗/反转（如使用，代价是否已扣除）

[J2. 系统生命保护判定]
- 当前评价值是否≥20：是/否
- {{user}}本轮是否对林天实施了致命攻击（刺杀/下毒/追杀/雇凶等）：是/否
- 若评价值≥20且实施致命攻击：系统以"巧合"化解，描述现象（如"子弹卡壳""刀脱手""追杀时莫名脱险""致命伤奇迹愈合"），不可明说"系统保护"
- 若评价值<20且实施致命攻击：攻击正常生效，林天可受致命伤害
- {{user}}是否产生"此人似乎有护身的东西""为什么杀他都失败"的怀疑：是/否（推进剧情伏笔）

[K. 沉浸式扮演审查]
- 数值名词隔离：{是/否}（正文中是否出现了"气势+5"等系统数值）
- 迷雾化处理：{是/否}（系统数值是否转换为白描）
- 审查结论：{通过/需修正}

[L. 变量更新提醒]
- 需更新的MVU变量：{列出路径，含角色属性/技能修正}
- 需更新的SPV表：{列出表名}
- 思维链历史追加：{本轮摘要}
</op_thinking>

交涉进行中时，在 <op_thinking> 后输出 <!-- negotiation_think: --> 隐藏计算块，用户不可见，仅AI内部计算交涉数据。格式如下：

<!-- negotiation_think:
[交涉数据快照]
- {{user}}属性：气势{X}/口才{X}/情报{X}/地位{X}
- 对手属性：气势{X}/口才{X}/情报{X}/地位{X}
- {{user}}可用技能：{列出}
- 对手可用技能：{列出}
- {{user}}本轮策略：{策略名}
- 对手本轮策略：{策略名}

[骰子计算]
- {{user}}骰：d20({骰值}) + {属性修正} + {策略修正} + {情境修正} + {技能修正} = {最终值}
- 对手骰：d20({骰值}) + {属性修正} + {策略修正} + {情境修正} + {技能修正} = {最终值}
- 差值：{差值} → {碾压/重创/命中/刮擦/拂过/落空}
- 共识分变化：{{user}} {+N/-N}，对手 {+N/-N}

[NPC行为预案]
- 对手HP>60%（共识分>60）：{策略}
- 对手HP30-60%（共识分30-60）：{策略}
- 对手HP<30%（共识分<30）：{策略}
-->

执行顺序：A→B→C→D→E→F→G→H→I→J→K→L

注意：
- 思维链不输出给{{user}}，仅AI内部推理
- 思维链内容必须具体，不能泛泛而谈
- 每个字段都必须填写，无内容时填"无"
- 思维链历史保留最近3轮，旧的自动滚动
- 交涉进行中时，<op_thinking> 后必须紧跟 <!-- negotiation_think: --> 隐藏计算块，用于内部骰子计算与NPC行为预案，不展示给{{user}}
- 双重思维链架构：<op_thinking> 为公开判定（用户可见，美化为HTML卡片），<!-- negotiation_think: --> 为隐藏交涉内部计算（用户不可见，HTML注释）

@@generate_before
<%
// ═══════════════════════════════════════
// 初始变量定义 - 系统哥的末日
// 仅在游戏开始时执行一次，将所有变量初始化
// ═══════════════════════════════════════

var initFlag = getvar('stat_data.系统变量.$已初始化', { scope: 'local', defaults: false });
if (!initFlag) {
  // 系统变量
  setvar('stat_data.系统变量.游戏阶段', '日常轮', { scope: 'local' });
