  // 反派林天状态（A9，已绑定8人，苏婉是第9目标，与SPV antagonist_state表同步）
  setvar('stat_data.反派状态.姓名', '林天', { scope: 'local' });
  setvar('stat_data.反派状态.财富等级', 'A9', { scope: 'local' });
