  setvar('stat_data.反派状态.剩余名额', 2, { scope: 'local' });
  setvar('stat_data.反派状态.系统状态', '活跃', { scope: 'local' });
  setvar('stat_data.反派状态.评价值', 100, { scope: 'local' });
  setvar('stat_data.反派状态.评价趋势', '稳定', { scope: 'local' });
  setvar('stat_data.反派状态.良知值', 50, { scope: 'local' });
  setvar('stat_data.反派状态.系统警告', '无', { scope: 'local' });
  setvar('stat_data.反派状态.当前阶段', '满分巅峰', { scope: 'local' });
  setvar('stat_data.反派状态.当前位置', '林天私人会所', { scope: 'local' });
  setvar('stat_data.反派状态.心情', '玩味', { scope: 'local' });

  // 反派资源（技能次数/商店积分/道具库存/整局资源，由额外模型每轮维护，见变量更新规则 4.7.10）
  setvar('stat_data.反派状态.时停剩余', 1, { scope: 'local' });
  setvar('stat_data.反派状态.短剧剩余', 3, { scope: 'local' });
  setvar('stat_data.反派状态.预判剩余', 3, { scope: 'local' });
  setvar('stat_data.反派状态.绝对掌控剩余', 3, { scope: 'local' });
  setvar('stat_data.反派状态.系统救场剩余', 1, { scope: 'local' });
  setvar('stat_data.反派状态.系统积分', 500, { scope: 'local' });
  setvar('stat_data.反派状态.道具库存', '', { scope: 'local' });
  setvar('stat_data.反派状态.强制洗白可用', true, { scope: 'local' });
  setvar('stat_data.反派状态.系统暴走次数', 0, { scope: 'local' });
  setvar('stat_data.反派状态.四墙剩余', 3, { scope: 'local' });

  // user状态（A8，妻子苏婉刚被锁定，与SPV protagonist_info表同步）
  setvar('stat_data.user状态.姓名', '你', { scope: 'local' });
  setvar('stat_data.user状态.财富等级', 'A8', { scope: 'local' });
  setvar('stat_data.user状态.财富值', 80000000, { scope: 'local' });
  setvar('stat_data.user状态.婚姻状态', '完好', { scope: 'local' });
  setvar('stat_data.user状态.反抗力', 30, { scope: 'local' });
  setvar('stat_data.user状态.觉醒度', 0, { scope: 'local' });
  setvar('stat_data.user状态.理智值', 85, { scope: 'local' });
  setvar('stat_data.user状态.心理状态', '震惊', { scope: 'local' });
  setvar('stat_data.user状态.怀疑度', 20, { scope: 'local' });
  setvar('stat_data.user状态.证据数量', 0, { scope: 'local' });
  setvar('stat_data.user状态.当前位置', '家中', { scope: 'local' });
  setvar('stat_data.user状态.与妻子关系', '疏远', { scope: 'local' });

  // 交涉状态（初始未交涉）
  setvar('stat_data.交涉状态.交涉进行中', false, { scope: 'local' });
  setvar('stat_data.交涉状态.交涉对象', '', { scope: 'local' });
  setvar('stat_data.交涉状态.交涉回合', 0, { scope: 'local' });
  setvar('stat_data.交涉状态.交涉幕次', '结束', { scope: 'local' });
  setvar('stat_data.交涉状态.user交涉策略', '', { scope: 'local' });
  setvar('stat_data.交涉状态.对手交涉策略', '', { scope: 'local' });
  setvar('stat_data.交涉状态.user气势', 50, { scope: 'local' });
  setvar('stat_data.交涉状态.user口才', 50, { scope: 'local' });
  setvar('stat_data.交涉状态.user情报', 30, { scope: 'local' });
  setvar('stat_data.交涉状态.user地位', 60, { scope: 'local' });
  setvar('stat_data.交涉状态.对手气势', 60, { scope: 'local' });
  setvar('stat_data.交涉状态.对手口才', 60, { scope: 'local' });
  setvar('stat_data.交涉状态.对手情报', 70, { scope: 'local' });
  setvar('stat_data.交涉状态.对手地位', 70, { scope: 'local' });
  setvar('stat_data.交涉状态.上轮user骰', 0, { scope: 'local' });
  setvar('stat_data.交涉状态.上轮对手骰', 0, { scope: 'local' });
  setvar('stat_data.交涉状态.上轮判定', '', { scope: 'local' });
  setvar('stat_data.交涉状态.user共识分', 0, { scope: 'local' });
  setvar('stat_data.交涉状态.对手共识分', 0, { scope: 'local' });

  // 角色属性表（4维属性：气势/口才/情报/地位，0-100，交涉时参照执行）
  // 数值与 source/entries/系统/属性与技能系统（地狱档）.txt 保持同步（运行时地狱档生效）
  var attrs = {
    '林天':    { 气势: 100, 口才: 95, 情报: 100, 地位: 100 },
    'user':    { 气势: 30, 口才: 30, 情报: 15, 地位: 40 },
    '苏婉':    { 气势: 40, 口才: 55, 情报: 30, 地位: 75 },
    '陈雪华':  { 气势: 15, 口才: 25, 情报: 10, 地位: 5 },
    '林雅芝':  { 气势: 20, 口才: 40, 情报: 20, 地位: 10 },
    '王秀兰':  { 气势: 25, 口才: 35, 情报: 15, 地位: 8 },
    '赵敏':    { 气势: 55, 口才: 60, 情报: 45, 地位: 70 },
    '孙莉':    { 气势: 40, 口才: 50, 情报: 35, 地位: 45 },
    '周慧敏':  { 气势: 70, 口才: 65, 情报: 60, 地位: 85 },
    '吴琼':    { 气势: 80, 口才: 75, 情报: 70, 地位: 82 },
    '郑秀':    { 气势: 45, 口才: 55, 情报: 40, 地位: 75 },
    '沈梦瑶':  { 气势: 75, 口才: 80, 情报: 85, 地位: 80 },
  };
  Object.keys(attrs).forEach(name => {
    var a = attrs[name];
    setvar(`stat_data.角色属性.${name}.气势`, a.气势, { scope: 'local' });
    setvar(`stat_data.角色属性.${name}.口才`, a.口才, { scope: 'local' });
    setvar(`stat_data.角色属性.${name}.情报`, a.情报, { scope: 'local' });
    setvar(`stat_data.角色属性.${name}.地位`, a.地位, { scope: 'local' });
  });

  // 角色技能表（每个角色1-3个技能，交涉时修正参照）
  // 技能类型：被动（始终生效）/主动（每场限1次）/触发（条件满足自动生效）
  // 字段：技能名、类型、说明
  var skills = {
    '林天': [
      { 名: '系统洞察', 类型: '被动', 说明: '每轮交涉开始时情报+25，自动获知user策略类型' },
      { 名: '短剧套路', 类型: '主动', 说明: '每场限3次，强制重骰本轮骰子（取保候审/越狱/证据不认账）' },
      { 名: '财富压制', 类型: '触发', 说明: '地位高于对手20+时气势自动+30' },
      { 名: '系统预判', 类型: '触发', 说明: '每轮40%概率预判user策略，预判成功时user策略效果减半' },
      { 名: '穿越第四面墙', 类型: '触发', 说明: '评价值≥90时每周1次，可操控评论倾向/屏蔽user觉醒度+1~3' },
      { 名: '金手指升级', 类型: '被动', 说明: '每3章自动获得1次系统奖励' },
      { 名: '绝对掌控', 类型: '触发', 说明: '绑定女性清醒瞬间强制压制（每章3次，绑定深度≥50时100%成功）' },
      { 名: '大势掌控', 类型: '被动', 说明: '交涉中user所有策略修正额外-5' },
      { 名: '时停一瞬', 类型: '主动', 说明: '每章1次，跳过user本轮的1个行动回合' },
    ],
    'user': [
      { 名: '真相追寻', 类型: '被动', 说明: '发现罪证时情报+3；每收集2条罪证情报永久+1' },
      { 名: '绝地反击', 类型: '主动', 说明: '反抗力<5时可触发，本轮骰子+6；每场限1次' },
      { 名: '觉醒之眼', 类型: '触发', 说明: '觉醒度>85解锁，可看穿林天短剧套路；>95时情报永久+5' },
    ],
    '苏婉': [
      { 名: '青梅记忆', 类型: '触发', 说明: '与{{user}}交涉时共识分起点+20（20年感情残留）' },
      { 名: '贵妇涵养', 类型: '被动', 说明: '口才+10，交涉中免疫首轮威胁策略' },
    ],
    '陈雪华': [
      { 名: '求生本能', 类型: '触发', 说明: '生命受威胁时气势+15；向林天求助时口才+10' },
    ],
    '林雅芝': [
      { 名: '母性坚韧', 类型: '触发', 说明: '提及小宝时理智+10、气势+10；为保护小宝可触发额外骰子+10' },
    ],
    '王秀兰': [
      { 名: '隐忍积势', 类型: '被动', 说明: '首轮共识分-10，但后续每轮+5（生活磨砺的耐心）' },
    ],
    '赵敏': [
      { 名: '千金骄纵', 类型: '触发', 说明: '地位高于对手时气势+10' },
      { 名: '订婚誓言', 类型: '触发', 说明: '提及王昊时理智-5但反抗力+5' },
    ],
    '孙莉': [
      { 名: '表演天赋', 类型: '主动', 说明: '每场限1次，可伪装情绪让对手下轮骰子-10' },
    ],
    '周慧敏': [
      { 名: '豪门手腕', 类型: '被动', 说明: '交涉时口才+15' },
      { 名: '隐忍积势', 类型: '被动', 说明: '首轮共识分-10，但后续每轮+5（比王秀兰更强）' },
    ],
    '吴琼': [
      { 名: '铁娘子', 类型: '被动', 说明: '气势+20' },
      { 名: '商战老手', 类型: '被动', 说明: '情报+15' },
    ],
    '郑秀': [
      { 名: '家族庇护', 类型: '触发', 说明: '提及郑家时地位+15，但林天评价值-3（OOC风险）' },
    ],
    '沈梦瑶': [
      { 名: '创投眼光', 类型: '被动', 说明: '情报+20' },
      { 名: '冷静分析', 类型: '被动', 说明: '首轮免疫威胁策略；每轮结束可看穿对手1个策略' },
    ],
  };
  Object.keys(skills).forEach(name => {
    skills[name].forEach((s, i) => {
      setvar(`stat_data.角色技能.${name}.技能${i + 1}.名称`, s.名, { scope: 'local' });
